mapper.select:
select department.*, user.name as userName, user2.name as teacherName
from department
left join user on department.user_id = user.id
left join user user2 on department.teacher_id = user2.id

     and department.id= #{id}
     and department.name like concat('%', #{name}, '%')
     and department.img= #{img}
     and department.description like concat('%', #{description}, '%')
     and department.user_id= #{userId}
     and department.teacher_id= #{teacherId}
     and department.time= #{time}

order by department.id asc
